#[path="../journal.rs"]mod journal;#[path="../owner.rs"]mod owner;
use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicUsize,Ordering};use glam::DVec3;use ingetrazo_core::mesh::{Mesh,MeshVertex};
struct Count;static LIVE:AtomicUsize=AtomicUsize::new(0);static PEAK:AtomicUsize=AtomicUsize::new(0);
fn added(n:usize){let total=LIVE.fetch_add(n,Ordering::Relaxed)+n;PEAK.fetch_max(total,Ordering::Relaxed);}
unsafe impl GlobalAlloc for Count{unsafe fn alloc(&self,l:Layout)->*mut u8{let p=unsafe{System.alloc(l)};if !p.is_null(){added(l.size());}p}unsafe fn dealloc(&self,p:*mut u8,l:Layout){LIVE.fetch_sub(l.size(),Ordering::Relaxed);unsafe{System.dealloc(p,l)}}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{let q=unsafe{System.realloc(p,l,n)};if !q.is_null(){if n>=l.size(){added(n-l.size());}else{LIVE.fetch_sub(l.size()-n,Ordering::Relaxed);}}q}}
#[global_allocator]static ALLOC:Count=Count;
fn main(){let mut mesh=Mesh::new();for i in 0..10000{mesh.vertices.push(MeshVertex::new(DVec3::new(10000.+i as f64*10.,0.,0.)));}let mut o=owner::JournalOwner::new(mesh).unwrap();let baseline=LIVE.load(Ordering::Relaxed);let mut points=vec![];let start=std::time::Instant::now();for i in 0..96{let mut t=o.begin();t.add_edge(DVec3::new(i as f64*2.,0.,0.),DVec3::new(i as f64*2.+1.,0.,0.)).unwrap();assert!(o.commit(t).unwrap());if [31,63,95].contains(&i){points.push(serde_json::json!({"depth":i+1,"live_bytes":LIVE.load(Ordering::Relaxed),"retained_baseline_entries":o.retained_baseline_entries(),"history_payload_bytes":o.history_payload_bytes()}));}}
let growth=LIVE.load(Ordering::Relaxed)-baseline;let payload=o.history_payload_bytes();let budget=o.budget().snapshot();assert!(growth<2*1024*1024);assert_eq!(o.history_counts(),(96,0));for _ in 0..96{o.undo().unwrap();}assert_eq!(o.mesh().vertices.len(),10000);for _ in 0..96{o.redo().unwrap();}assert_eq!(o.mesh().vertices.len(),10192);let before_replace=LIVE.load(Ordering::Relaxed);o.replace(Mesh::new()).unwrap();let after_replace=LIVE.load(Ordering::Relaxed);assert_eq!(o.history_counts(),(0,0));println!("{}",serde_json::json!({"base_vertices":10000,"history_depth":96,"memory_points":points,"baseline_live_bytes":baseline,"history_growth_bytes":growth,"retained_history_payload_bytes":payload,"owner_budget":{"history":budget.history,"staging":budget.staging,"preparation":budget.preparation,"peak":budget.peak,"vm_memory_included":false,"application_mesh_included":false},"peak_live_bytes":PEAK.load(Ordering::Relaxed),"replace_released_bytes":before_replace.saturating_sub(after_replace),"retained_baseline_entries":o.retained_baseline_entries(),"undo_redo_cycles":96,"elapsed_ms":start.elapsed().as_millis(),"production_writers_routed":false,"system_allocator_oom_proof":false}));}
